fix:
Accept pre-qualified domain abstractions (like an `Author` value object) into the domain method, delegating security checks to the application service or middleware boundary.
```rust
impl Forum {
    // Author represents a pre-validated, authorized entity in this context
    pub fn start_discussion(&self, author: Author, subject: &str) -> Discussion {
        Discussion::new(self.id, author.id, subject)
    }
}
